<?php

declare(strict_types=1);

namespace ParticleAcademy\FacebookLeadAds\Laravel\Http;

use ParticleAcademy\FacebookLeadAds\Laravel\Events\LeadgenReceived;
use ParticleAcademy\FacebookLeadAds\Triggers\Leadgen;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Http\Response;

/*
 * GENERATED by weaver from provider/ and its Laravel emitter (src/Laravel/Http/LeadgenWebhook.php). Do not edit;
 * a hand-edit is destroyed by the next protocol sync. Fix weaver and regenerate.
 */

/**
 * Facebook Lead Ads's leadgen delivery, VERIFIED before the app sees it: the raw body
 * exactly as received, the headers, checked by the trigger's own
 * scheme (hmac). A delivery that does not verify answers 401 with the
 * reason and dispatches nothing; one that does dispatches LeadgenReceived.
 */
final class LeadgenWebhook
{
    public function __invoke(Request $request): JsonResponse|Response
    {
        $raw = (string) $request->getContent();
        $headers = $request->headers->all();
        $result = Leadgen::verifyDelivery(
            $raw,
            $headers,
            config('connectors.facebook-lead-ads.credentials.appSecret'),
        );
        if (! $result['ok']) {
            return new JsonResponse(['ok' => false, 'reason' => $result['reason']], 401);
        }

        $payload = $raw === '' ? null : json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        event(new LeadgenReceived($payload, $headers));

        return new JsonResponse(['ok' => true]);
    }
}
